/// 🔬️ Measures every physical domain cell with an independent SQLite implementation.
fn en1997_independent_native_extent(snapshot:&En1997Snapshot)->(usize,usize){
 use std::{io::Write,process::{Command,Stdio}};
 let bytes=export_sqlite_database(&project(snapshot),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();
 let script=r#"import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()),{safeIntegers:true});let rows=0,bytes=0;for(const t of d.query("SELECT name FROM sqlite_schema WHERE type='table'").all()){for(const row of d.query('SELECT * FROM '+t.name).all()){rows++;for(const value of Object.values(row)){bytes+=value===null?0:typeof value==='string'?Buffer.byteLength(value):8;}}}d.close();await Bun.write(Bun.stdout,JSON.stringify([rows,bytes]));"#;
 let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));serde_json::from_slice(&output.stdout).unwrap()
}

/// 📏️ Admits exact semantic cell equality and refuses one missing byte on original native owners.
#[test]
fn sqlite_snapshot_en1997_original_native_semantic_extent_has_independent_exact_boundaries(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/📏️native-extent/🔣️.json")).unwrap();
 for annex in corpus["annexes"].as_array().unwrap(){for case in corpus["cases"].as_array().unwrap(){
  let mut snapshot=if let Some(word)=case["word"].as_str(){every_word(u64::from_str_radix(word,16).unwrap())}else{fixture()};
  snapshot.annex=if annex.as_str()==Some("En"){crate::document::AnnexChoice::En}else{crate::document::AnnexChoice::De};
  if case["id"].as_str()==Some("empty"){snapshot.layers.clear();snapshot.footings.clear();snapshot.piles.clear();snapshot.retaining_walls.clear();snapshot.slopes.clear();snapshot.uplift_cases.clear();}
  let rows=case["rows"].as_u64().unwrap()as usize;let bytes=case["valueBytes"].as_u64().unwrap()as usize;
  assert_eq!(en1997_independent_native_extent(&snapshot),(rows,bytes),"neutral independent extent {}",case["id"]);
  let limits=SqliteDatabaseLimits{max_rows:rows,max_value_bytes:bytes,..SqliteDatabaseLimits::default()};
  for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
   let ordinary=en1997_independent_native(&snapshot,encoding);
   assert_eq!(snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),ordinary);
   let restored=En1997Snapshot::decode_sqlite_snapshot_native(&ordinary,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(project(&restored),project(&snapshot));
   for(budget,kind)in[(SqliteDatabaseLimits{max_value_bytes:bytes-1,..limits},semio_framework_value::ValueRefusalKind::OwnershipLimit),(SqliteDatabaseLimits{max_rows:rows-1,..limits},semio_framework_value::ValueRefusalKind::WorkLimit)]{
    assert_eq!(snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,budget)).unwrap_err().kind,kind);
    assert_eq!(En1997Snapshot::decode_sqlite_snapshot_native(&ordinary,&mut SqliteSnapshotControl::new(&mut |_|true,budget)).unwrap_err().kind,kind);
   }
  }
  eprintln!("[DEBUG] EN1997 independent exact native cell boundary case={} annex={} rows={rows} bytes={bytes} both_native_encodings=true",case["id"],annex);
 }}
}

